<script setup lang="ts">
import {confirmAction} from '../ui/confirm'
import { ref,computed,onMounted,onUnmounted } from 'vue'
import { request } from '../api'
import { clone } from './types'
import { type Asset,type Place } from './archive'
import PlaceActions from './PlaceActions.vue'
import ResourceReferences from './ResourceReferences.vue'
import IndexMaintenance from './IndexMaintenance.vue'
import MediaTrash from './MediaTrash.vue'
import FolderSelect from './FolderSelect.vue'
import FolderManager from './FolderManager.vue'
import ArchiveRules from './ArchiveRules.vue'
import PrivatePreview from './PrivatePreview.vue'
import PlaceForm from './PlaceForm.vue'
const props=defineProps<{mode:'media'|'places'}>();const emit=defineEmits<{(e:'record',id:string):void}>()
const trashView=ref(false),trash=ref<{canLeave:()=>boolean|Promise<boolean>}|null>(null)
const folder=ref('*'),targetFolder=ref(''),category=ref(''),from=ref(''),until=ref(''),selected=ref<string[]>([]),folderGeneration=ref(0);let lastSelected=-1
function toggle(id:string,index:number,event:MouseEvent){const ids=items.value.map(x=>x.id);if(event.shiftKey&&lastSelected>=0){const [a,b]=[lastSelected,index].sort((a,b)=>a-b);selected.value=Array.from(new Set([...selected.value,...ids.slice(a,b!+1)]))}else if(selected.value.includes(id))selected.value=selected.value.filter(x=>x!==id);else selected.value.push(id);lastSelected=index}
async function batch(action:string){if(!selected.value.length||!await confirmAction('确认处理所选'+selected.value.length+'张图片？移除文件夹不删除文件；回收站逐项报告。'))return;await run(async()=>{const chosen=items.value.filter(x=>selected.value.includes(x.id)).map(x=>({id:x.id,expected_revision:x.revision}));if(action==='trash'||action==='unfile'){const result=await request('/admin/organization/media-actions',{method:'POST',body:JSON.stringify({action,confirmation:'逐项处理图片',items:chosen})});notice.value=result.items.map((x:any)=>x.id+'：'+(x.state==='completed'?'完成':JSON.stringify(x.reason))).join('；')}else{await request('/admin/archive/media-batch',{method:'POST',body:JSON.stringify({action,folder_id:targetFolder.value||null,category:category.value,confirmation:'执行批量操作',items:chosen})});notice.value='批量操作已完成'}await load()})}
const items=ref<(Asset|Place)[]>([]),draft=ref<Partial<Asset&Place>|null>(null),busy=ref(false),error=ref(''),notice=ref(''),q=ref(''),page=ref(1),total=ref(0),saved=ref('')
const pages=computed(()=>Math.max(1,Math.ceil(total.value/24)));const dirty=computed(()=>draft.value&&JSON.stringify(draft.value)!==saved.value);let alive=true
async function canLeave(){return (!trash.value||await trash.value.canLeave())&&!busy.value&&(!dirty.value||await confirmAction('有未保存的资源信息，确定放弃吗？'))}defineExpose({canLeave})
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){if(alive)error.value=String(e)}finally{if(alive)busy.value=false}}
async function load(){const data=await request('/admin/archive/'+props.mode+'?'+new URLSearchParams({page:String(page.value),q:q.value,...(props.mode==='media'?{...(folder.value==='*'?{}:folder.value?{folder_id:folder.value}:{unfiled:'true'}),...(from.value?{uploaded_from:from.value}:{}),...(until.value?{uploaded_to:until.value}:{})}:{})})) as {items:(Asset|Place)[];total:number};if(alive){selected.value=[];lastSelected=-1;items.value=data.items;total.value=data.total}}
async function select(id:string){if(!await canLeave())return;void run(async()=>{const data=await request('/admin/archive/'+props.mode+'/'+id);if(alive){draft.value=clone(data);if(data.usages)draft.value!.references=data.usages;saved.value=JSON.stringify(draft.value)}})}
async function search(){if(!await canLeave())return;draft.value=null;page.value=1;void run(load)}
async function turn(value:number){if(!await canLeave())return;draft.value=null;page.value=value;void run(load)}
async function refreshAfterPlaceChange(){draft.value=null;saved.value='';try{await load()}catch(e){error.value=String(e)}}
async function newPlace(){if(!await canLeave())return;draft.value={name:'',country:'',region:'',city:'',address:'',category:'',notes:'',latitude:null,longitude:null,active:true};saved.value=JSON.stringify(draft.value)}
async function upload(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);if(!files.length)return;if(!await canLeave()){input.value='';return}await run(async()=>{let uploaded=0;try{for(const file of files){const form=new FormData();form.append('file',file);if(folder.value==='')form.append('auto_archive','false');if(folder.value&&folder.value!=='*')form.append('folder_id',folder.value);await request('/admin/archive/media',{method:'POST',body:form});uploaded++}notice.value=`已上传 ${uploaded} 张图片`}catch(e){throw new Error(`已成功上传 ${uploaded} 张，其余未完成：${String(e)}`)}finally{page.value=1;await load()}});input.value=''}
async function save(){if(!draft.value)return;const d=draft.value;await run(async()=>{const payload=props.mode==='media'?{title:d.title,description:d.description,alt:d.alt,category:d.category||'',expected_revision:d.revision}:{name:d.name,country:d.country,region:d.region,city:d.city,address:d.address,category:d.category,notes:d.notes,latitude:d.latitude===''||d.latitude==null?null:String(d.latitude),longitude:d.longitude===''||d.longitude==null?null:String(d.longitude),active:d.active,...(d.id?{expected_revision:d.revision}:{})};const result=await request('/admin/archive/'+props.mode+(d.id?'/'+d.id:''),{method:d.id?'PUT':'POST',body:JSON.stringify(payload)});if(alive){draft.value={...clone(result),references:d.references||[]};saved.value=JSON.stringify(draft.value);notice.value='资源信息已保存';await load()}})}
async function remove(){if(!draft.value?.id||!await confirmAction('只将未被引用的图片移入删除状态，磁盘文件仍保留。继续吗？'))return;const d=draft.value;await run(async()=>{await request('/admin/archive/media/'+d.id,{method:'DELETE',body:JSON.stringify({expected_revision:d.revision})});draft.value=null;saved.value='';notice.value='图片已软删除，文件保留';await load()})}
async function original(){if(!draft.value?.id||!await confirmAction('原图可能包含EXIF/GPS等私人元数据。确认下载原图？'))return;const d=draft.value;await run(async()=>{const blob=await request('/library-media/'+d.id+'/original') as Blob;const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='original.'+({'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[d.mime_type||'']||'image');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
function openRecord(id:string){emit('record',id)}
function unload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{window.addEventListener('beforeunload',unload);void run(load)});onUnmounted(()=>{alive=false;window.removeEventListener('beforeunload',unload)})
</script>
<template><section class="resource-manager">
<p v-if="error" class="error" role="alert">{{error}}（未保存输入会保留）</p><p v-if="notice" class="notice" role="status">{{notice}}</p><p v-if="busy" class="muted">正在处理…</p>
<IndexMaintenance :disabled="busy||!!dirty" @busy="busy=$event" @changed="refreshAfterPlaceChange"/><ArchiveRules v-if="mode==='media'" :items="items.filter(x=>selected.includes(x.id))" @changed="folderGeneration++;load()"/><FolderManager v-if="mode==='media'" @changed="folderGeneration++;load()"/><button v-if="mode==='media'" class="quiet" :disabled="busy" @click="async()=>{if(await canLeave()){trashView=!trashView;await load()}}">{{trashView?'返回媒体库':'图片回收站'}}</button><MediaTrash v-if="mode==='media'&&trashView" ref="trash"/><template v-else><div class="card resource-tools"><h3>{{mode==='media'?'私人媒体库':'地点管理'}}</h3><p class="muted">{{mode==='media'?'原图独立保存；网页预览不含EXIF等原始元数据。移除文章引用不会删除图片。':'地点独立于内容类型保存，可由多篇记录复用。'}}</p>
<template v-if="mode==='media'"><label>按文件夹浏览<FolderSelect aria-label="按文件夹浏览" :key="folderGeneration" v-model="folder" all :disabled="busy"/></label><div class="editor-meta"><label>上传起始日期<input v-model="from" type="date"/></label><label>上传截止日期<input v-model="until" type="date"/></label></div></template><form @submit.prevent="search"><label>{{mode==='media'?'搜索图片标题或文件名':'搜索地点、城市、地址或类别'}}<input v-model="q" maxlength="200" type="search" /></label><button :disabled="busy">搜索资源</button></form>
<label v-if="mode==='media'">上传图片（可多选）<input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="busy" @change="upload" /></label><button v-else :disabled="busy" @click="newPlace">新建地点</button></div>
<section v-if="mode==='media'" class="card"><button type="button" class="quiet" @click="selected=items.map(x=>x.id)">全选当前页</button><button type="button" class="quiet" @click="selected=[]">清除选择</button><p>已选 {{selected.length}} 张（Shift可连续选择）；移除分类与回收站逐项报告；移动/分类仍保持整批事务。</p><label>移动目标<FolderSelect aria-label="移动目标" :key="folderGeneration" v-model="targetFolder"/></label><button :disabled="busy||!selected.length" @click="batch('move')">批量移动</button><label>图片分类<input v-model="category" maxlength="100"/></label><button :disabled="busy||!selected.length" @click="batch('category')">批量修改分类</button><button class="quiet" :disabled="busy||!selected.length" @click="batch('unfile')">从逻辑文件夹移除</button><button class="danger" :disabled="busy||!selected.length" @click="batch('trash')">批量移入回收站</button></section><div class="resource-layout"><div class="card"><div :class="mode==='media'?'media-grid':'place-list'"><div v-for="(item,index) in items" :key="item.id"><label v-if="mode==='media'" class="checks"><input type="checkbox" :checked="selected.includes(item.id)" @click="toggle(item.id,index,$event)"/>选择图片</label><button class="resource-item" :disabled="busy" @click="select(item.id)"><PrivatePreview v-if="mode==='media'" :id="item.id" :alt="(item as Asset).alt" /><strong>{{mode==='media'?((item as Asset).title||(item as Asset).filename):(item as Place).name}}</strong><small>{{mode==='media'?new Date((item as Asset).created_at).toLocaleDateString():((item as Place).city+' · '+((item as Place).active?'启用':'停用'))}}</small></button></div></div><p v-if="!items.length" class="muted">没有符合条件的资源。</p><div class="pagination"><button :disabled="busy||page<=1" class="quiet" @click="turn(page-1)">上一页</button><span>{{page}} / {{pages}} · {{total}}项</span><button :disabled="busy||page>=pages" class="quiet" @click="turn(page+1)">下一页</button></div></div>
<article class="card resource-detail"><p v-if="!draft" class="muted">选择资源查看或编辑信息。</p><template v-else><form @submit.prevent="save"><fieldset :disabled="busy"><template v-if="mode==='media'"><PrivatePreview :id="draft.id!" :alt="draft.alt||''" /><h3>图片信息</h3><p class="muted">{{draft.filename}} · {{draft.width}}×{{draft.height}} · {{Math.ceil((draft.size||0)/1024)}} KB</p><label>图片标题<input v-model="draft.title" maxlength="200" /></label><label>图片说明<textarea v-model="draft.description" maxlength="10000" rows="3" /></label><label>替代文本<input v-model="draft.alt" maxlength="1000" /></label></template><PlaceForm v-else :value="draft" /><button>保存资源信息</button></fieldset></form><section v-if="draft.id"><ResourceReferences :references="draft.references||[]" :disabled="busy" @record="openRecord"/><button class="quiet" :disabled="busy" @click="select(draft.id)">刷新资源与引用</button></section><PlaceActions v-if="mode==='places'&&draft.id" :key="draft.id+'-'+draft.revision" :place="draft" :disabled="busy||!!dirty" @busy="busy=$event" @changed="refreshAfterPlaceChange"/><div v-if="mode==='media'" class="actions"><button class="quiet" :disabled="busy" @click="original">下载原图（可能含EXIF）</button><button class="danger" :disabled="busy" @click="remove">软删除图片</button></div></template></article></div>
</template></section></template>
